import { runWord, type RunEventType } from '../reader/ruos'
import type { Snapshot } from '../reader/snapshot'

/** How a tile is coloured: the five states the pane names. */
export type MemberState = 'idle' | 'working' | 'blocked' | 'done' | 'failed'

export type PulseKind = 'read' | 'write'

/** One Claude Code agent loop as the engine reported it (`agent.spawn`, `$.agent.list()`), and what it has done since. */
export type LoopRecord = {
  id: string
  /** The agent type it runs as, without a plugin's prefix (`ruflo-swarm:coordinator` → `coordinator`). */
  role: string
  name?: string
  description?: string
  /** The numbers of the accepted ADRs the agent was told about when it was spawned (ruflo-console, ADR-480). */
  adrs?: number[]
  status: string
  calls: number
  errors: number
  lastTool?: string
  lastSubject?: string
  lastAtMs: number
  pulse?: { kind: PulseKind; atMs: number }
}

/** What the session's loops are doing, kept by the hooks between reads of the disk. */
export type Activity = {
  /** Claude Code's own subagents and teammates, by agent id; `lead` is the main loop. */
  loops: Map<string, LoopRecord>
  turnId: string | null
  isWorking: boolean
  /** The last few calls of each loop, newest last, for the activity view. */
  recent: Map<string, { tool: string; subject: string; isError: boolean; atMs: number }[]>
}

export const LEAD = 'lead'
export const PULSE_MS = 2_000
const RECENT = 12
const MAX_LOOPS = 200

export function newActivity(): Activity {
  return { loops: new Map(), turnId: null, isWorking: false, recent: new Map() }
}

export type Member = {
  id: string
  label: string
  role: string
  source: 'ruflo' | 'claude' | 'lead' | 'queen'
  state: MemberState
  /** The word under the colour, as the source said it (`busy`, `terminated`, `running`). */
  word: string
  pulse?: PulseKind
  isLeader: boolean
  claims: number
  calls: number
}

const WRITE_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit', 'MultiEdit'])
const READ_TOOLS = new Set(['Read', 'Glob', 'Grep', 'LS', 'NotebookRead'])

/** Whether a tool call reads or writes files, or neither (a pulse is for file work only). */
export function pulseOf(tool: string, command?: string): PulseKind | null {
  if (WRITE_TOOLS.has(tool)) {
    return 'write'
  }

  if (READ_TOOLS.has(tool)) {
    return 'read'
  }

  if ((tool === 'Bash' || tool === 'PowerShell') && command !== undefined) {
    return /(?:>|\btee\b|\bsed\s+-i|\bmv\b|\bcp\b|\brm\b|\bmkdir\b|\btouch\b|\bpatch\b|\bgit\s+(?:apply|checkout|restore|commit))/.test(command) ? 'write' : 'read'
  }

  return null
}

export const roleOf = (type: string): string => (type.includes(':') ? type.slice(type.lastIndexOf(':') + 1) : type) || 'agent'

function loopFor(activity: Activity, id: string, nowMs: number): LoopRecord {
  const held = activity.loops.get(id)

  if (held !== undefined) {
    return held
  }

  if (activity.loops.size >= MAX_LOOPS) {
    // Bounded: the loop not heard from longest makes room.
    const oldest = [...activity.loops.values()].filter(loop => loop.id !== LEAD).sort((a, b) => a.lastAtMs - b.lastAtMs)[0]

    if (oldest !== undefined) {
      activity.loops.delete(oldest.id)
      activity.recent.delete(oldest.id)
    }
  }

  const loop: LoopRecord = { id, role: id === LEAD ? 'lead' : 'agent', status: 'running', calls: 0, errors: 0, lastAtMs: nowMs }

  activity.loops.set(id, loop)

  return loop
}

/** A subagent the engine started (`agent.spawn`'s answer), with the type and name it was asked for. */
export function noteSpawn(activity: Activity, id: string, type: string, nowMs: number, name?: string, description?: string, adrs: readonly number[] = []): void {
  const loop = loopFor(activity, id, nowMs)

  loop.role = roleOf(type)
  loop.status = 'running'
  loop.lastAtMs = nowMs

  if (name !== undefined) {
    loop.name = name
  }

  if (description !== undefined) {
    loop.description = description
  }

  if (adrs.length > 0) {
    loop.adrs = adrs.slice(0, 8)
    loop.description = `${loop.description ?? ''}${loop.description === undefined ? '' : ' '}[guided by ADR ${adrs.slice(0, 8).join(', ')}]`.slice(0, 200)
  }
}

/** A tool call made by a loop (`agentId` absent: the main loop). Returns the pulse it lit, if any. */
export function noteCall(activity: Activity, agentId: string | undefined, tool: string, subject: string, nowMs: number, command?: string): PulseKind | null {
  const id = agentId ?? LEAD
  const loop = loopFor(activity, id, nowMs)
  const pulse = pulseOf(tool, command)

  loop.calls += 1
  loop.lastTool = tool
  loop.lastSubject = subject
  loop.lastAtMs = nowMs

  if (pulse !== null) {
    loop.pulse = { kind: pulse, atMs: nowMs }
  }

  return pulse
}

export function noteResult(activity: Activity, agentId: string | undefined, tool: string, subject: string, isError: boolean, nowMs: number): void {
  const id = agentId ?? LEAD
  const loop = loopFor(activity, id, nowMs)

  if (isError) {
    loop.errors += 1
  }

  activity.recent.set(id, [...(activity.recent.get(id) ?? []), { tool, subject, isError, atMs: nowMs }].slice(-RECENT))
}

/** How many failures in a row of one call make a loop stuck (ADR-477). */
export const STUCK_AFTER = 3

/** What a loop is called to the person, as its tile says it (a loop known only from its tool calls is said to be a subagent). */
export function loopLabel(activity: Activity, id: string): string {
  const loop = activity.loops.get(id)

  if (id === LEAD) return 'claude (main)'

  return loop === undefined ? `subagent …${id.slice(-4)}` : (loop.name ?? (loop.role === 'agent' ? `subagent …${id.slice(-4)}` : loop.role))
}

/** The call a loop has just failed STUCK_AFTER times running with the same subject (nothing in between), else null: the sign of a loop going round in circles. */
export function stuckCall(activity: Activity, agentId: string | undefined): { tool: string; subject: string } | null {
  const last = (activity.recent.get(agentId ?? LEAD) ?? []).slice(-STUCK_AFTER)
  const [first] = last

  if (first === undefined || last.length < STUCK_AFTER) return null

  return last.every(call => call.isError && call.tool === first.tool && call.subject === first.subject) ? { tool: first.tool, subject: first.subject } : null
}

/** A loop's own `turn.complete`: a subagent's answer is in. */
export function noteDone(activity: Activity, agentId: string, reason: string, nowMs: number): void {
  const loop = loopFor(activity, agentId, nowMs)

  loop.status = reason === 'answer' ? 'completed' : reason === 'aborted' ? 'killed' : 'failed'
  loop.lastAtMs = nowMs
}

/** `$.agent.list()` as the engine answered it: types and statuses for loops the hooks saw start before this module did. */
export function noteListed(activity: Activity, listed: readonly { id: string; type: string; status: string; description?: string; name?: string }[], nowMs: number): void {
  for (const agent of listed.slice(0, MAX_LOOPS)) {
    const loop = loopFor(activity, agent.id, nowMs)

    loop.role = roleOf(agent.type)
    loop.status = agent.status

    // A named Agent call runs as an in-process teammate, listed as type `teammate`: its name is what tells it apart.
    if (agent.name !== undefined && agent.name !== '') {
      loop.name = agent.name.slice(0, 40)
    }

    if (agent.description !== undefined && loop.description === undefined) {
      loop.description = agent.description
    }
  }
}

const RUFLO_STATES: Record<string, MemberState> = { idle: 'idle', busy: 'working', terminated: 'done' }
const RUN_STATES: Partial<Record<RunEventType, MemberState>> = { 'run.started': 'working', 'run.output': 'working', 'run.completed': 'done', 'run.failed': 'failed', 'run.stopped': 'done' }
const LOOP_STATES: Record<string, MemberState> = { running: 'working', pending: 'working', completed: 'done', failed: 'failed', killed: 'failed' }

/**
 * The tiles, in a stable order: the leader first, then ruflo's agents as the store lists them, then Claude Code's loops.
 * A ruflo agent with a blocked claim is blocked; a loop that has not called a tool for a while is idle, not working.
 */
export function membersOf(snapshot: Snapshot | null, activity: Activity, nowMs: number): Member[] {
  const claims = snapshot?.claims ?? []
  const claimsOf = (id: string) => claims.filter(claim => claim.claimant.id === id && claim.status !== 'completed')
  const queen = snapshot?.hive?.queen
  const members: Member[] = []

  if (queen !== undefined) {
    members.push({ id: queen.id, label: 'queen', role: 'queen', source: 'queen', state: 'working', word: `term ${queen.term ?? '?'}`, isLeader: true, claims: 0, calls: 0 })
  }

  const coordinator = (snapshot?.agents ?? []).find(agent => /coordinator|queen/.test(agent.type) && agent.status !== 'terminated')

  const events = snapshot?.ruos.events ?? []

  for (const agent of snapshot?.agents ?? []) {
    const held = claimsOf(agent.id)
    const isBlocked = held.some(claim => claim.status === 'blocked')
    const remote = agent.remote
    // On a ruOS desktop the newest lifecycle event for its run (or the agent) says where it stands.
    const run = remote === undefined ? undefined : events.filter(event => event.type !== 'desktop.state' && ((remote.runId !== undefined && event.runId === remote.runId) || event.agentId === agent.id)).sort((a, b) => b.ts - a.ts)[0]
    const runState = run === undefined ? undefined : RUN_STATES[run.type]

    members.push({
      id: agent.id,
      label: remote === undefined ? agent.type : `${agent.type} @${remote.desktopName}`,
      role: agent.type,
      source: 'ruflo',
      state: isBlocked ? 'blocked' : (runState ?? RUFLO_STATES[agent.status] ?? 'idle'),
      word: isBlocked ? 'blocked' : run !== undefined ? runWord(run) : agent.status,
      isLeader: queen === undefined && coordinator?.id === agent.id,
      claims: held.length,
      calls: 0,
    })
  }

  const loops = [...activity.loops.values()].sort((a, b) => (a.id === LEAD ? -1 : b.id === LEAD ? 1 : 0))

  for (const loop of loops) {
    const pulse = loop.pulse !== undefined && nowMs - loop.pulse.atMs < PULSE_MS ? loop.pulse.kind : undefined
    const isLead = loop.id === LEAD
    const isQuiet = nowMs - loop.lastAtMs > 30_000
    const base = isLead ? (activity.isWorking ? 'working' : 'idle') : (LOOP_STATES[loop.status] ?? 'idle')

    members.push({
      id: loop.id,
      // A loop known only from its tool calls (no spawn or listing reached the hooks) is said to be one, not given a role.
      label: isLead ? 'claude (main)' : (loop.name ?? (loop.role === 'agent' ? `subagent …${loop.id.slice(-4)}` : loop.role)),
      role: loop.role,
      source: isLead ? 'lead' : 'claude',
      state: base === 'working' && isQuiet && !isLead ? 'idle' : base,
      word: isLead ? (activity.isWorking ? 'turn running' : 'waiting') : loop.status,
      ...(pulse !== undefined && { pulse }),
      isLeader: isLead && queen === undefined && coordinator === undefined,
      claims: 0,
      calls: loop.calls,
    })
  }

  return members
}

/** True while some tile is still lit: the frame timer keeps drawing until every pulse has faded. */
export const isAnimating = (activity: Activity, nowMs: number): boolean =>
  [...activity.loops.values()].some(loop => loop.pulse !== undefined && nowMs - loop.pulse.atMs < PULSE_MS)

files.hooks/reader/parse.ts:
/**
 * Parsers for the files ruflo writes under `.claude-flow/` and `.swarm/`, and for the JSON `hooks route` prints.
 * Every one takes text from disk that another process wrote, so each tolerates any shape: what it cannot read
 * is left out, never guessed. Nothing here reads, keeps or returns the hive's `hiveToken`.
 */
import { remoteHostOf, type RemoteHost } from './ruos'

/** Text longer than this is not read: a store that size is not one the CLI wrote, and parsing it would stall a hook. */
export const MAX_TEXT = 4_000_000
/** At most this many records of one kind are kept; the rest are counted, not drawn. */
export const MAX_RECORDS = 1_000

export type SwarmInfo = {
  id: string
  topology: string
  status: string
  maxAgents?: number
  strategy?: string
  consensus?: string
  agentIds: string[]
  updatedAt?: string
}

export type AgentRecord = {
  id: string
  type: string
  status: string
  health?: number
  taskCount?: number
  model?: string
  createdAt?: string
  /** Where the agent runs, when ruflo-ruos placed it on a ruOS desktop (`config.host`, see ./ruos). */
  remote?: RemoteHost
}

export type TaskRecord = {
  id: string
  type: string
  description: string
  priority: string
  status: string
  progress?: number
  assignedTo: string[]
}

export type ClaimRecord = {
  issueId: string
  status: string
  claimant: { kind: 'agent' | 'human'; id: string; agentType?: string }
  progress?: number
  handoffTo?: string
  isStealable: boolean
}

export type Proposal = { id: string; type: string; status: string; strategy: string; votesFor: number; votesAgainst: number; proposedBy: string }
export type Decision = { id: string; type: string; result: string; votesFor: number; votesAgainst: number; decidedAt: string }

export type HiveInfo = {
  topology: string
  strategy?: string
  queen?: { id: string; term?: number }
  workers: string[]
  pending: Proposal[]
  history: Decision[]
}

export type RoutePick = {
  task: string
  agent: string
  confidence: number
  matched: boolean
  pattern?: string
  alternatives: { agent: string; confidence: number }[]
  method?: string
  atMs: number
}

const ID = /^[A-Za-z0-9][A-Za-z0-9._:@-]{0,127}$/

/** Plain printable text of at most `max` characters: no control characters reach the terminal. */
export function plain(value: unknown, max = 200): string {
  if (typeof value !== 'string') {
    return ''
  }

  const cleaned = value.replace(/[\u0000-\u001f\u007f-\u009f​-‏‪-‮⁦-⁩]/g, ' ').replace(/\s+/g, ' ').trim()

  return cleaned.length <= max ? cleaned : `${cleaned.slice(0, Math.max(0, max - 1))}…`
}

/** An id as ruflo mints them (`agent-…`, `task-…`, `proposal-…`), or null: only such a string ever reaches an argv. */
export function idOf(value: unknown): string | null {
  return typeof value === 'string' && ID.test(value) ? value : null
}

const numberOf = (value: unknown): number | undefined => (typeof value === 'number' && Number.isFinite(value) ? value : undefined)
const stringOf = (value: unknown, max = 80): string | undefined => (typeof value === 'string' && value !== '' ? plain(value, max) : undefined)
const recordOf = (value: unknown): Record<string, unknown> | null =>
  value !== null && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : null

/** JSON text to a plain object, or null for anything else (too long, malformed, an array, a scalar). */
export function jsonObject(text: string | null): Record<string, unknown> | null {
  if (text === null || text.length > MAX_TEXT) {
    return null
  }

  try {
    return recordOf(JSON.parse(text))
  } catch {
    return null
  }
}

const valuesOf = (value: unknown): unknown[] => {
  const record = recordOf(value)

  return record === null ? [] : Object.values(record).slice(0, MAX_RECORDS)
}

/** `.claude-flow/swarm/swarm-state.json`: the running swarm, else the one updated last. */
export function parseSwarmStore(text: string | null): SwarmInfo | null {
  const swarms = valuesOf(jsonObject(text)?.swarms)
    .map(recordOf)
    .flatMap(swarm => {
      const id = idOf(swarm?.swarmId)

      if (swarm === null || id === null) {
        return []
      }

      const config = recordOf(swarm.config)

      return [
        {
          id,
          topology: stringOf(swarm.topology, 40) ?? 'unknown',
          status: stringOf(swarm.status, 40) ?? 'unknown',
          ...(numberOf(swarm.maxAgents) !== undefined && { maxAgents: numberOf(swarm.maxAgents) }),
          ...(stringOf(config?.strategy, 40) !== undefined && { strategy: stringOf(config?.strategy, 40) }),
          ...(stringOf(config?.consensusMechanism, 40) !== undefined && { consensus: stringOf(config?.consensusMechanism, 40) }),
          agentIds: (Array.isArray(swarm.agents) ? swarm.agents : []).slice(0, MAX_RECORDS).flatMap(agent => (idOf(agent) !== null ? [agent as string] : [])),
          ...(stringOf(swarm.updatedAt, 40) !== undefined && { updatedAt: stringOf(swarm.updatedAt, 40) }),
        } satisfies SwarmInfo,
      ]
    })

  const byRecency = (a: SwarmInfo, b: SwarmInfo) => (b.updatedAt ?? '').localeCompare(a.updatedAt ?? '')

  return [...swarms.filter(swarm => swarm.status === 'running')].sort(byRecency)[0] ?? [...swarms].sort(byRecency)[0] ?? null
}

/** `.swarm/state.json`: the pointer `swarm init` leaves, which names the swarm and its strategy. */
export function parseSwarmPointer(text: string | null): { id: string; topology?: string; strategy?: string; status?: string } | null {
  const value = jsonObject(text)
  const id = idOf(value?.id)

  if (value === null || id === null) {
    return null
  }

  return {
    id,
    ...(stringOf(value.topology, 40) !== undefined && { topology: stringOf(value.topology, 40) }),
    ...(stringOf(value.strategy, 40) !== undefined && { strategy: stringOf(value.strategy, 40) }),
    ...(stringOf(value.status, 40) !== undefined && { status: stringOf(value.status, 40) }),
  }
}

/** `.claude-flow/agents/store.json`. */
export function parseAgents(text: string | null): AgentRecord[] {
  return valuesOf(jsonObject(text)?.agents).flatMap(entry => {
    const agent = recordOf(entry)
    const id = idOf(agent?.agentId)

    if (agent === null || id === null) {
      return []
    }

    return [
      {
        id,
        type: stringOf(agent.agentType, 40) ?? 'agent',
        status: stringOf(agent.status, 20) ?? 'unknown',
        ...(numberOf(agent.health) !== undefined && { health: numberOf(agent.health) }),
        ...(numberOf(agent.taskCount) !== undefined && { taskCount: numberOf(agent.taskCount) }),
        ...(stringOf(agent.model, 40) !== undefined && { model: stringOf(agent.model, 40) }),
        ...(stringOf(agent.createdAt, 40) !== undefined && { createdAt: stringOf(agent.createdAt, 40) }),
        ...(remoteHostOf(agent.config) !== null && { remote: remoteHostOf(agent.config) as RemoteHost }),
      },
    ]
  })
}

/** `.claude-flow/tasks/store.json`. */
export function parseTasks(text: string | null): TaskRecord[] {
  return valuesOf(jsonObject(text)?.tasks).flatMap(entry => {
    const task = recordOf(entry)
    const id = idOf(task?.taskId)

    if (task === null || id === null) {
      return []
    }

    return [
      {
        id,
        type: stringOf(task.type, 40) ?? 'task',
        description: plain(task.description, 300),
        priority: stringOf(task.priority, 20) ?? 'normal',
        status: stringOf(task.status, 20) ?? 'unknown',
        ...(numberOf(task.progress) !== undefined && { progress: numberOf(task.progress) }),
        assignedTo: (Array.isArray(task.assignedTo) ? task.assignedTo : []).slice(0, 50).flatMap(agent => (idOf(agent) !== null ? [agent as string] : [])),
      },
    ]
  })
}

/** `.claude-flow/claims/claims.json`: issue claims (who works on what), not the authorization file `.claude-flow/claims.json`. */
export function parseClaims(text: string | null): ClaimRecord[] {
  const store = jsonObject(text)
  const stealable = recordOf(store?.stealable) ?? {}

  return valuesOf(store?.claims).flatMap(entry => {
    const claim = recordOf(entry)
    const issueId = idOf(claim?.issueId)
    const claimant = recordOf(claim?.claimant)

    if (claim === null || issueId === null || claimant === null) {
      return []
    }

    const isAgent = claimant.type === 'agent'
    const who = idOf(isAgent ? claimant.agentId : claimant.userId)

    if (who === null) {
      return []
    }

    const handoff = recordOf(claim.handoffTo)
    const handoffTo = idOf(handoff?.agentId ?? handoff?.userId)

    return [
      {
        issueId,
        status: stringOf(claim.status, 30) ?? 'unknown',
        claimant: { kind: isAgent ? 'agent' : 'human', id: who, ...(stringOf(claimant.agentType, 40) !== undefined && { agentType: stringOf(claimant.agentType, 40) }) },
        ...(numberOf(claim.progress) !== undefined && { progress: numberOf(claim.progress) }),
        ...(handoffTo !== null && { handoffTo }),
        isStealable: claim.status === 'stealable' || Object.hasOwn(stealable, issueId),
      },
    ]
  })
}

const votesOf = (value: unknown): { votesFor: number; votesAgainst: number } => {
  const votes = valuesOf(value)

  return { votesFor: votes.filter(vote => vote === true).length, votesAgainst: votes.filter(vote => vote === false).length }
}

/** `.claude-flow/hive-mind/state.json`, without its capability token. */
export function parseHive(text: string | null): HiveInfo | null {
  const hive = jsonObject(text)

  if (hive === null || hive.initialized !== true) {
    return null
  }

  const queen = recordOf(hive.queen)
  const queenId = idOf(queen?.agentId)
  const consensus = recordOf(hive.consensus)

  const pending = (Array.isArray(consensus?.pending) ? consensus.pending : []).slice(-50).flatMap(entry => {
    const proposal = recordOf(entry)
    const id = idOf(proposal?.proposalId)

    return proposal === null || id === null
      ? []
      : [
          {
            id,
            type: stringOf(proposal.type, 40) ?? 'proposal',
            status: stringOf(proposal.status, 20) ?? 'pending',
            strategy: stringOf(proposal.strategy, 20) ?? 'unknown',
            proposedBy: stringOf(proposal.proposedBy, 60) ?? 'unknown',
            ...votesOf(proposal.votes),
          },
        ]
  })

  const history = (Array.isArray(consensus?.history) ? consensus.history : []).slice(-50).flatMap(entry => {
    const decision = recordOf(entry)
    const id = idOf(decision?.proposalId)
    const votes = recordOf(decision?.votes)

    return decision === null || id === null
      ? []
      : [
          {
            id,
            type: stringOf(decision.type, 40) ?? 'proposal',
            result: stringOf(decision.result, 20) ?? 'unknown',
            votesFor: numberOf(votes?.for) ?? 0,
            votesAgainst: numberOf(votes?.against) ?? 0,
            decidedAt: stringOf(decision.decidedAt, 40) ?? '',
          },
        ]
  })

  return {
    topology: stringOf(hive.topology, 40) ?? 'unknown',
    ...(stringOf(hive.consensusStrategy, 30) !== undefined && { strategy: stringOf(hive.consensusStrategy, 30) }),
    ...(queenId !== null && { queen: { id: queenId, ...(numberOf(queen?.term) !== undefined && { term: numberOf(queen?.term) }) } }),
    workers: (Array.isArray(hive.workers) ? hive.workers : []).slice(0, MAX_RECORDS).flatMap(worker => (idOf(worker) !== null ? [worker as string] : [])),
    pending,
    history,
  }
}

/**
 * What `hooks route --format json` printed (log lines may come first), or the `hooks_route` MCP tool answered, as one pick.
 * The router's own `matched` flag is kept as it said it; whether the confidence clears a threshold is the view's call.
 */
export function parseRoute(text: string, atMs: number): RoutePick | null {
  const start = text.indexOf('{')
  const value = start < 0 ? null : jsonObject(text.slice(start, Math.min(text.length, start + 200_000)))
  const primary = recordOf(value?.primaryAgent)
  const agent = stringOf(primary?.type, 40)
  const confidence = numberOf(primary?.confidence)

  if (value === null || agent === undefined || confidence === undefined) {
    return null
  }

  const routing = recordOf(value.routing)

  return {
    task: plain(value.task, 200),
    agent,
    confidence: Math.max(0, Math.min(1, confidence)),
    matched: value.matched === true,
    ...(stringOf(value.matchedPattern, 40) !== undefined && { pattern: stringOf(value.matchedPattern, 40) }),
    alternatives: (Array.isArray(value.alternativeAgents) ? value.alternativeAgents : []).slice(0, 3).flatMap(entry => {
      const alt = recordOf(entry)
      const type = stringOf(alt?.type, 40)
      const score = numberOf(alt?.confidence)

      return type !== undefined && score !== undefined ? [{ agent: type, confidence: Math.max(0, Math.min(1, score)) }] : []
    }),
    ...(stringOf(routing?.method, 40) !== undefined && { method: stringOf(routing?.method, 40) }),
    atMs,
  }
}

/** A pick held in `$.store` read back: every field checked, as anything else from storage is. */
export function routeFromStore(value: unknown): RoutePick | null {
  const pick = recordOf(value)

  if (pick === null || typeof pick.task !== 'string' || typeof pick.agent !== 'string' || numberOf(pick.confidence) === undefined || numberOf(pick.atMs) === undefined) {
    return null
  }

  return parseRoute(JSON.stringify({ task: pick.task, matched: pick.matched, matchedPattern: pick.pattern, primaryAgent: { type: pick.agent, confidence: pick.confidence }, alternativeAgents: [], routing: { method: pick.method } }), numberOf(pick.atMs) ?? 0)
}

files.hooks/reader/snapshot.ts:
import {
  parseAgents,
  parseClaims,
  parseHive,
  parseSwarmPointer,
  parseSwarmStore,
  parseTasks,
  type AgentRecord,
  type ClaimRecord,
  type HiveInfo,
  type SwarmInfo,
  type TaskRecord,
} from './parse'
import { EVENTS_MAX, parseEvents, parseHosts, RUOS_EVENTS, RUOS_HOSTS, type RunEvent, type RuosHost } from './ruos'

/** The file calls a reader makes, as `$.fs` answers them; every one may be refused. */
export type ReaderFs = {
  read: (path: string) => Promise<string>
  stat: (path: string) => Promise<{ mtimeMs?: number; size?: number } | undefined>
}

/** Where ruflo keeps each fact, relative to the session's working directory. */
export const FILES = {
  swarm: '.claude-flow/swarm/swarm-state.json',
  pointer: '.swarm/state.json',
  agents: '.claude-flow/agents/store.json',
  tasks: '.claude-flow/tasks/store.json',
  claims: '.claude-flow/claims/claims.json',
  hive: '.claude-flow/hive-mind/state.json',
} as const

export type FileKey = keyof typeof FILES

export type Snapshot = {
  swarm: SwarmInfo | null
  agents: AgentRecord[]
  tasks: TaskRecord[]
  claims: ClaimRecord[]
  hive: HiveInfo | null
  /** ruOS desktops that host swarm agents (ruflo-ruos): null hosts when the snapshot file is absent. */
  ruos: { hosts: RuosHost[] | null; events: RunEvent[]; note?: string }
  /** The facts that are not on disk (no file, unreadable, or not in a shape ruflo writes), by key. */
  missing: FileKey[]
  /** True when any of ruflo's swarm files is there at all: the pane has something of its own to show. */
  hasSwarm: boolean
  readAtMs: number
}

/** The text of each file as last read, by path, with the mtime it was read at: an unchanged file is not read again. */
export type ReadCache = Map<string, { mtimeMs: number; size: number; text: string }>

async function textOf(fs: ReaderFs, cache: ReadCache, path: string): Promise<string | null> {
  try {
    const stat = await fs.stat(path)
    const mtimeMs = stat?.mtimeMs ?? -1
    const size = stat?.size ?? -1
    const held = cache.get(path)

    if (held !== undefined && mtimeMs >= 0 && held.mtimeMs === mtimeMs && held.size === size) {
      return held.text
    }

    const text = await fs.read(path)

    cache.set(path, { mtimeMs, size, text })

    return text
  } catch {
    cache.delete(path)

    return null
  }
}

/** Reads every swarm fact ruflo keeps on disk, in parallel; a refused or absent file is a missing fact, never an error. */
export async function readSnapshot(fs: ReaderFs, cache: ReadCache, nowMs: number): Promise<Snapshot> {
  const keys = Object.keys(FILES) as FileKey[]
  const texts = await Promise.all(keys.map(key => textOf(fs, cache, FILES[key])))
  const text = (key: FileKey) => texts[keys.indexOf(key)] ?? null

  const pointer = parseSwarmPointer(text('pointer'))
  const stored = parseSwarmStore(text('swarm'))
  // The pointer names the swarm `swarm init` made last; the store has its members. Either alone still names a swarm.
  const swarm: SwarmInfo | null =
    stored ??
    (pointer !== null
      ? { id: pointer.id, topology: pointer.topology ?? 'unknown', status: pointer.status ?? 'unknown', agentIds: [], ...(pointer.strategy !== undefined && { strategy: pointer.strategy }) }
      : null)

  const ruos = await readRuos(fs, cache)
  const parsed = {
    swarm,
    agents: parseAgents(text('agents')),
    tasks: parseTasks(text('tasks')),
    claims: parseClaims(text('claims')),
    hive: parseHive(text('hive')),
    ruos,
  }

  const missing = keys.filter(key => {
    switch (key) {
      case 'swarm':
        return stored === null
      case 'pointer':
        return pointer === null
      case 'hive':
        return parsed.hive === null
      default:
        return text(key) === null
    }
  })

  return {
    ...parsed,
    missing,
    hasSwarm: swarm !== null || parsed.agents.length > 0 || parsed.hive !== null,
    readAtMs: nowMs,
  }
}

/** The ruOS host snapshot and the tail of its event log. The log is read whole (there is no ranged read), so past a size it is not read. */
async function readRuos(fs: ReaderFs, cache: ReadCache): Promise<Snapshot['ruos']> {
  const hosts = parseHosts(await textOf(fs, cache, RUOS_HOSTS))
  let size = -1

  try {
    size = (await fs.stat(RUOS_EVENTS))?.size ?? -1
  } catch {
    return { hosts, events: [] }
  }

  if (size > EVENTS_MAX) {
    return { hosts, events: [], note: `ruOS event log is ${Math.round(size / 1_000_000)} MB: not read` }
  }

  return { hosts, events: parseEvents(await textOf(fs, cache, RUOS_EVENTS)) }
}

